//! Файл: settings/catalog/write_path.rs
//! Что делает: настройки задачи t158 — путь сделки без ожиданий: очередь уведомлений (решение 340), очередь записи
//! журнала (решение 341), учёт сделок своим соединением в своём файле (решение 342). Отдельный файл: base.rs — общий
//! для многих задач. Все необязательные, значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, разделы «Уведомления» и «Система»).

use super::{G, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 340–342. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static WRITE_PATH: &[SettingDef] = &[
    d("Уведомления", "notify.queue_max", K::Integer, L::Positive, "сообщений", G, "Решение 340 (Тигран 16.11: уведомление не имеет права задерживать сделку): уведомления Telegram всегда уходят фоновой очередью — шаг сделки не ждёт отправки; порядок уведомлений сохраняется (одна очередь, по порядку постановки). Это — предел очереди: сколько уведомлений может ждать отправки; больше — новое не ставится, потеря считается и пишется в «Журнал» (notify.queue_lost на 1-й, 2-й, 4-й… потере). Не задана — очередь без предела (ничего не теряется; при долгом сбое Telegram сообщения копятся в памяти и уходят с опозданием)").optional(),
    d("Система", "journal.queue_max", K::Integer, L::Positive, "записей", G, "Решение 341: запись «Журнала» не ждётся — запись уходит в очередь, отдельный поток пишет накопленное одной транзакцией по порядку (меньше ожидания общего замка базы у сделок и пачки пулов DEX). Это — предел очереди; больше — запись теряется со счётом (запись journal.queue_lost). При первом включении ставится обработчик остановки: Ctrl+C / SIGTERM дописывает очередь и завершает бот с кодом 0. Не задана — как раньше: каждая запись ждётся своей транзакцией").optional(),
    d("Система", "ledger.own_db", K::Bool, L::None, "да/нет", G, "Решение 342 (Тигран 16.11: «Сделка имеет своё отдельное соединение и ни с кем не конкурирует»): да — записи учёта сделок (открытие, шаги, закрытие) пишутся своим соединением и своим потоком в отдельный файл ledger.sqlite рядом с основной базой; запись журнала, окна, эпизода, настроек и отчётов не может встать перед ней (у этого файла нет других писателей). Загрузка сделок читает оба файла (по сделке — последняя запись), поэтому включение и выключение на ходу ничего не теряют и переноса старой базы не требуют. Нет или не задана — как раньше: учёт в основной базе").optional(),
    d("Система", "ledger.synchronous", K::Choice, L::None, "режим SQLite", G, "Решение 342: PRAGMA synchronous соединения учёта сделок (ledger.own_db = да); https://www.sqlite.org/pragma.html#pragma_synchronous. FULL — как основная база сейчас: коммит переживает и падение бота, и потерю питания. NORMAL (режим WAL) — коммит переживает падение бота, но последние коммиты могут пропасть при потере питания или падении ОС (тогда после запуска сделка может оказаться без последнего шага — «прервана перезапуском» по прежней записи). EXTRA — ещё надёжнее FULL. OFF — не включать для денег. Не задана — значение SQLite по умолчанию (FULL); снятие настройки действует после перезапуска").choices(&["FULL", "NORMAL", "EXTRA", "OFF"]).optional(),
];
